class RequestOptions(TypedDict, total=False):
    practice_id: str
    idempotency_key: str
    organization_id: str
    actor_id: str
    actor_type: str
    timeout: float
    max_retries: int

class AffinityError(Exception):
    def __init__(self, error: ApiError):
        self.status = error.status_code
        body = error.body if isinstance(error.body, dict) else error.body.dict(by_alias=True) if hasattr(error.body, "dict") else {}
        self.code = body.get("code", "api_error")
        self.request_id = body.get("requestId")
        self.retryable = self.status in (408, 429, 500, 502, 503, 504)
        self.retry_after = None
        headers = {k.lower(): v for k, v in (error.headers or {}).items()}
        value = headers.get("retry-after")
        if value:
            try:
                self.retry_after = max(0, float(value))
            except ValueError:
                try:
                    self.retry_after = max(0, (parsedate_to_datetime(value) - datetime.now(timezone.utc)).total_seconds())
                except (TypeError, ValueError):
                    pass
        super().__init__(f"Affinity API request failed ({self.status})")

class _Shared:
    def __init__(self, generated):
        self.generated = generated
        self.identity = None
        self.lock = threading.Lock()
        self.async_lock = asyncio.Lock()

class _Context:
    def __init__(self, shared, practice_id=None):
        self.shared = shared
        self.practice_id = practice_id

    def prepare(self, op, ids, params, options):
        params, options = dict(params or {}), dict(options or {})
        if op["rootOnly"] and self.practice_id:
            raise ValueError("Use the root client for platform-wide operations")
        if self.practice_id and options.get("practice_id") and self.practice_id != options["practice_id"]:
            raise ValueError("Conflicting practice ID")
        if "practice_id" in params or "practiceId" in params:
            raise ValueError("Pass practice_id in request options")
        if op["id"] == "updatePatient" and params.get("status") == "archived": params["status"] = "inactive"
        key = options.get("idempotency_key")
        if key is not None and (not isinstance(key, str) or not key.strip()):
            raise ValueError("idempotency_key must not be empty")
        if op["idempotency"] == "required" and not key:
            raise ValueError("A persisted idempotency_key is required for this operation")
        if op["idempotency"] == "none" and key:
            raise ValueError("This endpoint does not support idempotency keys")
        if op["idempotency"] == "auto" and not key:
            key = str(uuid.uuid4())
        if len(ids) != len(op["ids"]) or any(not isinstance(v, str) or not v.strip() for v in ids):
            raise ValueError("A resource ID is required")
        if key: params["idempotency_key"] = key
        params.update(zip(op["ids"], ids))
        for field, header in op["headers"].items():
            if field in options: params[header] = options[field]
        params["request_options"] = {k: options[k] for k in ("timeout", "max_retries") if k in options}
        return params, options

    def practice(self, op, params, options):
        selected = options.get("practice_id", self.practice_id)
        if op["practice"] != "none":
            identity = self.shared.identity
            if identity.subject_type == "practice":
                if selected and selected != identity.subject_id:
                    raise ValueError("Practice context conflicts with the API key")
                selected = identity.subject_id
            if not selected: raise ValueError("A platform key requires practice_id for this operation")
            if op["practice"] != "order": params["practice_id"] = selected
        elif options.get("practice_id"):
            raise ValueError("This endpoint does not accept practice context")
        return selected

    def method(self, op):
        target = self.shared.generated
        for part in op["group"].split("."): target = getattr(target, part)
        return getattr(target, op["method"])

    def call(self, op, ids, params=None, options=None):
        params, options = self.prepare(op, ids, params, options)
        try:
            if op["practice"] != "none":
                with self.shared.lock:
                    if self.shared.identity is None:
                        self.shared.identity = self.shared.generated.api_keys.get_access().service_account
            selected = self.practice(op, params, options)
            if op["practice"] == "order":
                order = self.shared.generated.orders.get(params["order_id"])
                if order.practice_id != selected: raise ValueError("Order does not belong to the selected practice")
                if op["id"] == "getOrder": return order
            return self.method(op)(**params)
        except ApiError as error:
            raise AffinityError(error) from None

    async def call_async(self, op, ids, params=None, options=None):
        params, options = self.prepare(op, ids, params, options)
        try:
            if op["practice"] != "none":
                async with self.shared.async_lock:
                    if self.shared.identity is None:
                        self.shared.identity = (await self.shared.generated.api_keys.get_access()).service_account
            selected = self.practice(op, params, options)
            if op["practice"] == "order":
                order = await self.shared.generated.orders.get(params["order_id"])
                if order.practice_id != selected: raise ValueError("Order does not belong to the selected practice")
                if op["id"] == "getOrder": return order
            return await self.method(op)(**params)
        except ApiError as error:
            raise AffinityError(error) from None

    def iterate(self, op, ids, params=None, options=None):
        query = dict(params or {})
        if query.get("ending_before") is not None: raise ValueError("iterate supports forward pagination")
        while True:
            page = self.call(op, ids, query, options)
            yield from page.data
            if not page.has_more: return
            cursor = page.data[-1].id if page.data else None
            if not cursor or cursor == query.get("starting_after"): raise ValueError("Pagination did not advance")
            query["starting_after"] = cursor

    async def iterate_async(self, op, ids, params=None, options=None):
        query = dict(params or {})
        if query.get("ending_before") is not None: raise ValueError("iterate supports forward pagination")
        while True:
            page = await self.call_async(op, ids, query, options)
            for item in page.data: yield item
            if not page.has_more: return
            cursor = page.data[-1].id if page.data else None
            if not cursor or cursor == query.get("starting_after"): raise ValueError("Pagination did not advance")
            query["starting_after"] = cursor

