class Affinity:
    def __init__(self, api_key: str, **configuration):
        if not api_key.strip(): raise ValueError("An API key is required")
        self._context = _Context(_Shared(GeneratedAffinity(api_key=api_key, **configuration)))

    def for_practice(self, practice_id: str) -> Affinity:
        if not practice_id.strip(): raise ValueError("practice_id is required")
        if self._context.practice_id and self._context.practice_id != practice_id: raise ValueError("Conflicting practice ID")
        client = object.__new__(type(self))
        client._context = _Context(self._context.shared, practice_id)
        return client

    @property
    def account(self) -> AccountResource:
        return AccountResource(self._context)

    @property
    def api_keys(self) -> ApiKeysResource:
        return ApiKeysResource(self._context)

    @property
    def catalog(self) -> CatalogResource:
        return CatalogResource(self._context)

    @property
    def locations(self) -> LocationsResource:
        return LocationsResource(self._context)

    @property
    def orders(self) -> OrdersResource:
        return OrdersResource(self._context)

    @property
    def patients(self) -> PatientsResource:
        return PatientsResource(self._context)

    @property
    def pharmacies(self) -> PharmaciesResource:
        return PharmaciesResource(self._context)

    @property
    def practices(self) -> PracticesResource:
        return PracticesResource(self._context)

    @property
    def team(self) -> TeamResource:
        return TeamResource(self._context)

    @property
    def webhooks(self) -> WebhooksResource:
        return WebhooksResource(self._context)

